const w = div('left:0;top:90px;width:150px;height:60px;background:#BFD9F2;border-radius:12px', vis);
const dirty = div('left:0;top:90px;width:150px;height:60px;background:#8B6B4A;border-radius:12px;opacity:0', vis);
const wave = svg(150, 20, '<path d="M0 10 Q19 0 37 10 T75 10 T112 10 T150 10" stroke="#fff" stroke-width="4" fill="none"/>', 'left:0;top:84px', vis);
mv.show(w, T.t0 + .1); mv.show(wave, T.t0 + .1);
const tr = div('left:50px;top:-10px;width:50px;height:50px;opacity:0', vis, ico('trash-2', 50, NAVY, 2.5));
mv.show(tr, T.t0 + .2);
mv.slide(tr, T.hit - .6, 'translateY(0px)', 'translateY(85px)');
mv.show(dirty, T.hit);
mv.wobble(w, T.hit);
snd('hit', T.hit);

const n = 4;
for (let i = 0; i < n; i++) {
  const p = div('left:' + (i * 38) + 'px;top:50px;width:36px;height:50px;opacity:0', vis, ico('user', 36, i === 0 ? ACC : NAVY, 2.5));
  mv.pop(p, T.t0 + .1 + i * .1);
  mv.dim(p, T.hit + i * .15);
}
snd('hit', T.hit);

const card = div('left:15px;top:35px;width:120px;height:80px;background:#EEF0F4;border-radius:16px', vis);
mv.pop(card, T.t0 + .1);
const q = div('left:45px;top:30px;width:60px;height:90px;opacity:0;font-family:KeySans;font-size:80px;line-height:90px;text-align:center;color:' + ACC, vis, '?');
